static void SceneMain(OMOBJ *object)
{
    switch (object->mode) {
        case 0:
            object->mode = 1;
            /* fallthrough */
        case 1:
            if (!omSysExitReq) {
                break;
            }
            object->mode = 2;
            /* fallthrough */
        case 2:
            WipeCreate(WIPE_MODE_OUT, WIPE_TYPE_NORMAL, 60);
            HuAudFadeOut(1000);
            object->mode = 3;
            /* fallthrough */
        case 3:
            if (WipeStatGet() == 0) {
                OptionStateKill(optionState);
                if (rumbleF != GWGameStat.rumble) {
                    omSysExitReq = 0;
                    KillScene();
                }
                omOvlReturnEx(1, 1);
            }
            break;
    }
}

static void ExecState(OMOBJ *object)
{
    StateWork *work = object->data;

    switch (object->mode) {
        case 0:
            object->mode = 1;
            /* fallthrough */
        case 1:
            WipeCreate(WIPE_MODE_IN, WIPE_TYPE_PREV, 60);
            object->mode = 2;
            break;
        case 2:
            if (WipeStatGet() != 0 || work->window->state != 0) {
                break;
            }
            OptionRoomExecModeSet(optionRoom, 1);
            object->mode = 3;
            /* fallthrough */
        case 3:
            if (OptionRoomExecModeGet(optionRoom) != 0) {
                break;
            }
            object->mode = 4;
            /* fallthrough */
        case 4:
            OptionWinAnimIn(work->window);
            OptionWinMesSet(work->window, MAKE_MESSID(47, 167)); // Would you like to leave?
            object->mode = 5;
            /* fallthrough */
        case 5:
            if (work->window->state != 0) {
                break;
            }
            OptionWinChoiceSet(work->window, 1);
            object->mode = 6;
            /* fallthrough */
        case 6:
            if (work->window->state != 0) {
                break;
            }
            OptionWinAnimOut(work->window);
            if (work->window->choice == 0) {
                work->quitTimer = 0;
                object->mode = 7;
            }
            else {
                object->mode = 2;
            }
            break;
        case 7:
            object->mode = 8;
            work->quitTimer = 0;
            /* fallthrough */
        case 8:
            if (work->window->state == 0 && work->quitTimer++ >= 60) {
                omSysExitReq = 1;
            }
            break;
    }
}

